
<style>*{box-sizing:border-box}.container{max-width:1200px;margin:30px auto;padding:0 16px}.tool-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:20px;align-items:start}.tool-main,.tool-sidebar{background:#fff;border:1px solid #e5e9f0;border-radius:20px;padding:25px;box-shadow:0 14px 40px rgba(20,30,70,.05)}.tool-sidebar{position:sticky;top:88px;max-height:calc(100vh - 108px);overflow:auto}.tool-sidebar a{display:block;padding:9px 10px;margin:3px 0;border-radius:9px;text-decoration:none;color:#536075;font-size:13px;font-weight:700}.tool-sidebar a:hover,.tool-sidebar a.active{background:#f0efff;color:#635bff}.editors{display:grid;grid-template-columns:1fr 1fr;gap:15px}.input,.preview{width:100%;min-height:400px;padding:15px;border:1px solid #dfe4ec;border-radius:12px;font:15px/1.6 system-ui;background:#fff}.preview{overflow:auto}.btn{border:0;border-radius:10px;padding:12px 18px;background:#635bff;color:#fff;font-weight:800;cursor:pointer;margin:4px 5px 12px 0}@media(max-width:800px){.tool-layout,.editors{grid-template-columns:1fr}.tool-sidebar{position:static;max-height:330px}.input,.preview{min-height:300px}}</style><main class="container"><div class="tool-layout"><section class="tool-main"><h1>Markdown to HTML</h1><p>Convert Markdown into clean HTML instantly in your browser.</p><div class="editors"><textarea id="input" class="input" placeholder="# Hello World

Write **bold**, *italic*, [links](https://example.com), lists and code here..."></textarea><div id="preview" class="preview">HTML preview will appear here.</div></div><br><button class="btn" onclick="convert()">Convert to HTML</button><button class="btn" onclick="copyHTML()">Copy HTML</button><button class="btn" onclick="clearAll()">Clear</button><details><summary>Generated HTML</summary><pre id="html"></pre></details></section><aside class="tool-sidebar"><h2>🛠️ All Tools</h2><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','png-to-jpg.php'=>'↩️ PNG to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','gif-maker.php'=>'🎞️ GIF Maker','pdf-to-jpg.php'=>'📄 PDF to JPG','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','png-to-pdf.php'=>'📄 PNG to PDF','text-to-pdf.php'=>'📝 Text to PDF','qr-generator.php'=>'🔐 QR Code Generator','qr-reader.php'=>'📷 QR Code Reader','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','bmi-calculator.php'=>'⚖️ BMI Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer','lorem-ipsum-generator.php'=>'📄 Lorem Ipsum','unix-timestamp.php'=>'🕐 Unix Timestamp','timestamp-converter.php'=>'🕐 Timestamp Converter','uuid-generator.php'=>'🆔 UUID Generator','random-number-generator.php'=>'🎲 Random Number Generator','sort-lines.php'=>'↕️ Sort Lines','remove-extra-spaces.php'=>'🧹 Remove Extra Spaces','reverse-text.php'=>'↔️ Reverse Text','text-to-slug.php'=>'🔗 Text to Slug','markdown-to-html.php'=>'📝 Markdown to HTML','json-formatter.php'=>'{} JSON Formatter','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','url-encoder.php'=>'🔗 URL Encoder'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/tool.php">View All Tools →</a></aside></div></main><script>let generated='';const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');function convert(){let s=document.getElementById('input').value;let lines=s.split(/\r?\n/),out=[],inList=false;for(let line of lines){if(/^\s*[-*+]\s+/.test(line)){if(!inList){out.push('<ul>');inList=true}out.push('<li>'+inline(line.replace(/^\s*[-*+]\s+/,''))+'</li>');continue}else if(inList){out.push('</ul>');inList=false}if(!line.trim()){out.push('');continue}let m=line.match(/^(#{1,6})\s+(.+)$/);if(m){out.push('<h'+m[1].length+'>'+inline(m[2])+'</h'+m[1].length+'>')}else if(/^```/.test(line)){out.push('<pre><code>');while(lines.length&&lines[0]!=='```')out.push(esc(lines.shift()));out.push('</code></pre>')}else out.push('<p>'+inline(line)+'</p>')}if(inList)out.push('</ul>');generated=out.join('\n');document.getElementById('preview').innerHTML=generated;document.getElementById('html').textContent=generated}function inline(s){s=esc(s);s=s.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/__([^_]+)__/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/_([^_]+)_/g,'<em>$1</em>').replace(/!\[([^\]]*)\]\(([^)]+)\)/g,'<img alt="$1" src="$2">').replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1</a>');return s}async function copyHTML(){if(!generated)convert();await navigator.clipboard.writeText(generated)}function clearAll(){document.getElementById('input').value='';generated='';document.getElementById('preview').textContent='HTML preview will appear here.';document.getElementById('html').textContent=''}</script>
